{
  "name": "jev-guard",
  "version": "0.1.0",
  "description": "Sends each Bash command to the jev model on OpenRouter before it runs, like auto mode, and blocks the ones it classifies as dangerous.",
  "userConfig": {
    "apiKey": {
      "type": "string",
      "title": "OpenRouter API key",
      "description": "Key used to call the classifier. If empty, the OPENROUTER_API_KEY environment variable is used. With neither, commands are not checked.",
      "sensitive": true
    },
    "model": {
      "type": "string",
      "title": "Classifier model",
      "description": "OpenRouter decisions model id (called through /api/alpha/decisions).",
      "default": "typesafe/jev-1.14"
    },
    "blockThreshold": {
      "type": "number",
      "title": "Block threshold",
      "description": "Commands jev rates at or above this chance of being unsafe (0 to 1) are blocked. Lower is stricter.",
      "default": 0.5
    },
    "onError": {
      "type": "string",
      "title": "When the classifier fails",
      "description": "What happens to a command if OpenRouter errors, times out or gives an unreadable answer: deny blocks it, allow lets it run.",
      "options": [
        "deny",
        "allow"
      ],
      "default": "deny"
    }
  }
}
